// Generated by Claude - Opus 5.5
// Where the creatures are, as fractions of the backdrop (0 = left/top, 1 = right/bottom),
// and the visitors' timetable, which the drawing and the sounds both follow.

/** Creatures that stay in one spot: their center. */
export const SPOTS = {
  molina: { x: 0.86, y: 0.8 },
  turtle: { x: 0.13, y: 0.87 },
  jelly: { x: 0.24, y: 0.4 },
} as const

/** Something that crosses the pond: along x (at height y) or along y (at x). */
export type Mover = {
  axis: 'x' | 'y'
  at: number // the fixed coordinate: y for a horizontal trip, x for a vertical one
  from: number
  to: number
  seconds: number
}

/** Creatures that cross the pond forever, timed from the clock so every redraw agrees. */
export const LOOPS = {
  yellow: { axis: 'x', at: 0.25, from: 1.15, to: -0.25, seconds: 42 }, // fish schools
  blue: { axis: 'x', at: 0.52, from: -0.15, to: 1.15, seconds: 55 },
  puffer: { axis: 'x', at: 0.46, from: -0.15, to: 1.15, seconds: 70 },
  tetras: { axis: 'x', at: 0.13, from: 1.1, to: -0.2, seconds: 36 },
  shrimp: { axis: 'x', at: 0.915, from: 1.05, to: -0.05, seconds: 90 },
  snail: { axis: 'x', at: 0.92, from: 1.05, to: -0.05, seconds: 240 },
} as const satisfies Record<string, Mover>

/**
 * Visitors keep a timetable from the clock: once every `every` seconds each one
 * swims through (taking `seconds`), starting `offset` seconds into the cycle.
 * The drawing and the sounds both read it, so nothing has to redraw when a
 * visitor arrives. `calls`: seconds into the trip when it calls out.
 */
export const VISITORS = {
  // Silent events (no calls). The whale comes first so it is drawn behind everything.
  whale: { axis: 'x', at: 0.17, from: -0.5, to: 1.5, seconds: 70, every: 330, offset: 150, calls: [] },
  squid: { axis: 'x', at: 0.24, from: -0.2, to: 1.2, seconds: 12, every: 150, offset: 40, calls: [] },
  sardines: { axis: 'x', at: 0.4, from: 1.3, to: -0.4, seconds: 22, every: 110, offset: 85, calls: [] },
  burst: { axis: 'y', at: 0.56, from: 1.02, to: -0.12, seconds: 8, every: 45, offset: 12, calls: [] }, // bubbles from the sand
  // Visitors that call out.
  orca: { axis: 'x', at: 0.3, from: 1.3, to: -0.3, seconds: 30, every: 240, offset: 0, calls: [7, 17] },
  turtle: { axis: 'x', at: 0.6, from: -0.2, to: 1.2, seconds: 36, every: 180, offset: 70, calls: [10] },
  manta: { axis: 'x', at: 0.68, from: 1.25, to: -0.25, seconds: 32, every: 210, offset: 140, calls: [8] },
  seahorse: { axis: 'y', at: 0.4, from: 1.1, to: -0.15, seconds: 28, every: 270, offset: 200, calls: [4, 14] },
} as const satisfies Record<string, Mover & { every: number; offset: number; calls: readonly number[] }>
export type VisitorKind = keyof typeof VISITORS

/** Seconds into a visitor's cycle at time `nowMs`; it is on screen while this is under its `seconds`. */
export const visitPhase = (kind: VisitorKind, nowMs: number) => {
  const v = VISITORS[kind]
  return (((nowMs / 1000 - v.offset) % v.every) + v.every) % v.every
}

/** How far along (0 to 1) a looping creature is at time `nowMs`. */
export const loopProgress = (m: Mover, nowMs: number) => ((nowMs / 1000) / m.seconds) % 1

